# Rainbow Table Attack in Python

A rainbow table is a precomputed table used to crack hash-based authentication systems. It maps plaintext passwords to their hashed outputs (ciphertext), allowing rapid comparison against a hash store. You cannot decrypt the hash to find the original password; instead, you verify the hash exists in the table for a given guess.

This script demonstrates how to generate and use a rainbow table for the MD5 hash function. MD5 is considered broken for password storage now, but it serves as a baseline for understanding the concept.

# Setup
import hashlib
import os

# Initialize the rainbow table
def init_table(path):
    table = {}

    # Load in the hashes
    with open(path, 'rb') as f:
        while True:
            try:
                data = f.read(4096)
                if not data:
                    break
                h = hashlib.md5(data).hexdigest()
                if h not in table:
                    table[h] = set()
                table[h].add(data)
            except EOFError:
                break

    return table

# Generate keys
def generate_keys():
    # Store .txt files in same folder
    folder = './rainbow'
    if not os.path.exists(folder):
        os.makedirs(folder)
    filepath = os.path.join(folder, 'keys.txt')
    with open(filepath, 'w') as f:
        keys = set(range(16))
        for i in keys:
            f.write(f'{i}\n')
        f.close()
    return filepath

# Main Function
def crack_hash(hash_file, password_hash):
    table = init_table(hash_file)
